UPDATE draft_reserveinfo
SET onedayclass_price = #{priceUpdated}
WHERE status = 'READY'
  AND selectedDate = #{selectedDate}
  AND merchant_uid = #{merchant_uid}
  AND user_code = #{userCode}

UPDATE draft_reserveinfo
SET status = 'CANCEL'
WHERE status = 'READY'
  AND selectedDate = #{selectedDate}
  AND merchant_uid = #{merchant_uid}
  AND user_code = #{userCode}
